#!/usr/bin/env python3
"""Standalone conservative Set72 encoding arithmetic. No product imports.

Source only until root approves this exact file and public input lock. Synthetic
maximum-width compositions need not be valid states. No expected protocol state
or derived wallet output is generated by this diagnostic.
"""
import argparse
import hashlib
import json
from pathlib import Path

H=lambda raw:hashlib.sha256(raw).hexdigest()
MAXTIME=253402300799999
HEX='f'*64

def canonical(value):
    s=json.dumps(value,ensure_ascii=False,allow_nan=False,separators=(',',':'))
    return s.replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029').encode('utf8')

def guarded(args):
    if not args.execute:raise ValueError('--execute required')
    raw=args.approved_lock.read_bytes()
    if H(raw)!=args.approved_lock_sha256:raise ValueError('approval hash')
    lock=json.loads(raw)
    if lock.get('approved_by')!='root' or lock.get('execution_authorized') is not True or lock.get('purpose')!='set72-sizing':raise ValueError('approval')
    if lock['sources']!={'sizing.py':H(Path(__file__).read_bytes())}:raise ValueError('source')
    raw=args.input_lock.read_bytes()
    if H(raw)!=lock['input_lock_sha256']:raise ValueError('input lock')
    ilock=json.loads(raw);catpath=args.input_lock.parent/ilock['catalog'];craw=catpath.read_bytes()
    if H(craw)!=ilock['catalog_sha256']:raise ValueError('catalog')
    rows=json.loads(craw)['files'];paths={};total=0;root=args.inputs.resolve(strict=True)
    if len(rows)!=ilock['input_count'] or len(rows)>128:raise ValueError('input count')
    for row in rows:
        rel=Path(row['path'])
        if rel.is_absolute() or '..' in rel.parts or row['path'] in paths:raise ValueError('input path')
        path=root
        for part in rel.parts:
            path=path/part
            if path.is_symlink():raise ValueError('symlink input')
        if not path.is_file() or root not in path.resolve().parents:raise ValueError('input path')
        raw=path.read_bytes()
        if len(raw)!=row['bytes'] or H(raw)!=row['sha256']:raise ValueError('input changed')
        paths[row['path']]=path;total+=len(raw)
    if total!=ilock['input_bytes'] or total>16*1024*1024:raise ValueError('input size')
    recipe=json.loads(paths[ilock['recipe']].read_bytes())
    if H(paths[ilock['recipe']].read_bytes())!=ilock['recipe_sha256']:raise ValueError('recipe')
    return json.loads(paths[recipe['paths']['current']].read_bytes()),H(args.input_lock.read_bytes()),H(args.approved_lock.read_bytes())

def measure(current):
    rows=[]
    for initial in current['original_manifests']:
        binding=dict(version=1,inventory_id=HEX,authority_id=HEX,account_id=HEX,principal_id=HEX,
          provision_id=HEX,hosted_vault_id=HEX,retention_id=HEX,wallet_owner_id=HEX,source_binding_id=HEX,
          manager_schema=13,max_allocations=1024,max_bytes=4194304,max_plan_attempts=128,
          max_branch_index=4096,initial_manifest=initial)
        request=dict(version=1,kind='withdrawal_change',consumer_id=HEX,purpose=84,branch=1,
          withdrawal_binding_id=HEX,recipient='a'*90,recipient_script='f'*68,amount_atoms=2100000000000000,
          fee_rate_atoms_per_kb=1000,fee_ceiling_atoms=100000,min_confirmations=1,input_purpose=84,
          change_purpose=84,account=0,tx_version=1,input_sequence=4294967295,lock_time=0,sighash_type=1)
        reservation=dict(version=1,sequence=1024,allocation_id=HEX,binding_id=HEX,request=request,
          purpose=84,branch=1,start_index=3968,end_index=4096,selected_index=4095,
          invalid_indices=list(range(3968,4095)),address='a'*90,script='f'*44,reserved_at_ms=MAXTIME)
        row=dict(reservation=reservation,reservation_digest=HEX,phase='consumed',completed_at_ms=MAXTIME,
          wallet_record_digest=HEX,draft_digest=HEX)
        marker=dict(application='slug-hosted-allocation-inventory',version=1,inventory_id=HEX,binding=binding)
        meta=dict(version=1,marker_sha256=HEX,revision=2048,allocations=1024,clock_high_water_ms=MAXTIME,
          active_allocation_id=HEX,cursors=[4096]*8)
        guard=dict(version=1,state='locked',inventory_id=HEX,authority_id=HEX,account_id=HEX,
          wallet_owner_id=HEX,source_binding_id=HEX,initial_manifest_sha256=HEX,binding_id=HEX)
        local_meta=dict(version=1,guard_sha256=HEX,completed_sequence=1024,cursors=[4096]*8)
        link=dict(version=1,inventory_id=HEX,binding_id=HEX,sequence=1024,allocation_id=HEX,
          reservation_digest=HEX,request_digest=HEX,outcome='consumed',purpose=84,branch=1,
          start_index=3968,end_index=4096,selected_index=4095,invalid_indices=list(range(3968,4095)),
          address='a'*90,script='f'*44,cursors_before=[4096]*8,cursors_after=[4096]*8,
          withdrawal_binding_id=HEX,withdrawal_operation_id=HEX,draft_digest=HEX)
        inventories=[dict(fixture=f,inventory_id=HEX) for f in ('zero256','incrementing256')]
        hosted_init=dict(version=1,mode='local-hosted-fixture-pool',descriptor_id=HEX,authority_id=HEX,
          coordinator_id=HEX,hosted_vault_id=HEX,provider_driver_id='local-published-fixture-evidence-v1',
          wrapper_id='public-fixture-wrapper-v1',verifier_config_hash=HEX,identity_config_sha256=HEX,
          provider_config_sha256=HEX,vault_config_sha256=HEX,
          wallets=[dict(fixture=f,wallet_owner_id=HEX) for f in ('zero256','incrementing256')])
        outer=dict(application='slug-hosted-allocation-owner',version=1,mode='local-hosted-recovery-pool',
          hosted_init=hosted_init,inventories=inventories)
        init=dict(version=1,guard_sha256=HEX,inventories=inventories)
        setup=dict(version=1,fixture='incrementing256',guard_sha256=HEX,pool_allocation_id=HEX,binding=binding)
        ready=dict(version=1,guard_sha256=HEX,source_binding_id=HEX,
          fixtures=[dict(fixture=f,inventory_id=HEX,binding_id=HEX,binding_sha256=HEX,pool_allocation_id=HEX)
                    for f in ('zero256','incrementing256')])
        values=dict(binding=binding,request=request,reservation=reservation,row=row,meta=meta,
          guard=guard,local_meta=local_meta,local_link=link,marker=marker,outer_guard=outer,init=init,setup=setup,ready=ready)
        files={'marker','outer_guard','init','setup','ready'}
        lengths={k:len(canonical(v))+(1 if k in files else 0) for k,v in values.items()}
        lengths['batch']=len('allocation/')+64+lengths['row']+4+lengths['meta']
        limits=dict(request=2048,row=4096,meta=4096,guard=2048,local_meta=2048,local_link=4096,
          marker=8192,outer_guard=32768,init=16384,setup=8192,ready=16384,batch=12288)
        for k,cap in limits.items():
            if lengths[k]>cap:raise ValueError(k+' exceeds proposed cap')
        rows.append(dict(gym_id=initial['gym_id'],encoded_bytes=lengths,limits=limits,
          host_1024_width_bytes=1024*(len('allocation/')+64+lengths['row'])+4+lengths['meta'],
          local_1024_width_bytes=1024*(4+lengths['local_link'])+4+lengths['local_meta']+
             len('hostedallocationguard')+lengths['guard']+len('slug-hosted-allocation-v1')+len('records')))
    return dict(version=1,scope='synthetic conservative codec size arithmetic; not expected valid states',
      note='All variable strings here have ASCII address/hex grammar; six-byte JSON escaping is inapplicable. Locked guard plus nonempty binding and all-max cursors are deliberate unreachable size compositions.',
      fixtures=rows,independent_store_cap=4194304,count_cap=1024,
      accounting=dict(host_old_and_staged=8388608,local_audit_reference=4194304,
                      remaining_row_metadata_indexes_plans=4194304,per_store=16777216,two_stores=33554432),
      disclaimer='Count/byte limits are independent. Not all maximum rows need fit together. Logical accounting is not total heap usage; no helper wire or private export is generated.')

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--execute',action='store_true')
    p.add_argument('--approved-lock',type=Path,required=True);p.add_argument('--approved-lock-sha256',required=True)
    p.add_argument('--input-lock',type=Path,required=True);p.add_argument('--inputs',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True);a=p.parse_args()
    current,inputs,approval=guarded(a);result=measure(current)
    result.update(input_lock_sha256=inputs,approved_lock_sha256=approval)
    if guarded(a)[1:]!=(inputs,approval):raise ValueError('changed binding')
    raw=(json.dumps(result,indent=2)+'\n').encode()
    with a.output.open('xb') as f:f.write(raw)
    print(json.dumps(dict(bytes=len(raw),sha256=H(raw))))

if __name__=='__main__':main()
